schemas:
{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What does VNW Media help businesses with?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We plan and build websites, SEO and local search, paid advertising, social media, content, reputation, and lead paths. The mix depends on the business goals and its current setup."
      }
    },
    {
      "@type": "Question",
      "name": "Where is VNW Media based?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We are based in Morganville, New Jersey. We work with businesses across New Jersey, New York, and other markets through direct communication and a remote-first process."
      }
    },
    {
      "@type": "Question",
      "name": "How does a project begin?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "We discuss your goals, current website, audience, service areas, and constraints. Then we recommend a focused scope and explain the deliverables before work begins."
      }
    },
    {
      "@type": "Question",
      "name": "Who will I work with?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The team brings together strategy, design, development, search, and campaigns. We identify the people and responsibilities for each engagement in the proposal."
      }
    },
    {
      "@type": "Question",
      "name": "Can we start with one service?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. A project can begin with a website, SEO, Google Ads, or another priority and expand only when useful. We scope each service to the problem it is meant to solve."
      }
    },
    {
      "@type": "Question",
      "name": "What happens after launch?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Depending on the engagement, ongoing support can include website maintenance, content, SEO, ads, measurement, and improvements. The exact support and timing are agreed in the scope."
      }
    }
  ]
}

{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "What types of work does VNW Media create?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "VNW Media creates custom websites, local SEO foundations, lead-generation landing pages, Google PPC campaign paths, social content systems, reputation-focused pages, eCommerce experiences, and digital strategy for local and service-based businesses."
      }
    },
    {
      "@type": "Question",
      "name": "Do you only design websites?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "No. The website is usually the center of the system, but the work often includes messaging, SEO structure, conversion strategy, content, reputation signals, campaign alignment, and post-launch improvement planning."
      }
    },
    {
      "@type": "Question",
      "name": "Can VNW redesign an existing website?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. VNW can improve an existing website or create a new build when the current structure, messaging, speed, design, or conversion path is limiting growth."
      }
    },
    {
      "@type": "Question",
      "name": "Which industries does VNW support?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The portfolio includes automotive, home services, daycare, healthcare, restaurants, eyecare, real estate, legal, retail, professional services, and local businesses that need stronger visibility and lead flow."
      }
    },
    {
      "@type": "Question",
      "name": "How long does a website or marketing project take?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Timing depends on scope, content, functionality, approvals, and integrations. After discovery, VNW provides a practical project plan with clear phases and responsibilities."
      }
    },
    {
      "@type": "Question",
      "name": "Can results be measured after launch?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. When tracking and platform access are available, the work can be evaluated through relevant signals such as calls, forms, appointment actions, visibility, engagement, sales, or lead quality."
      }
    },
    {
      "@type": "Question",
      "name": "How should a business start?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Start with a review of the current website, business goals, customer journey, service areas, and marketing channels. From there, VNW can recommend the right scope and priority order."
      }
    }
  ]
}
